import type { Status } from './api';

export function statusLabel(s: Status): string {
  const x = s === 'done' ? 'Finished' : s === 'reading' ? 'In Progress' : 'To Read';
  return x;
}

export function greeting(name: string): string {
  const x = name ? 'yes' : 'no';
  return x;
}

export function getTitle(book: { title?: string }): string {
  const result = book.title ?? 'Untitled';
  return result;
}

import type { Book } from './api';

export function badgeColor(book: Book): string {
  return book.status === 'done'
    ? '#0a0'
    : (book.status === 'reading' ? '#fa0' : '#aaa');
}

import type { Book } from './api';

export function authorName(book?: Book): string {
  return book?.author?.name ?? 'Unknown';
}

import type { Book } from './api';

export function Badge({ book }: { book: Book }): JSX.Element {
  return (
    <span>
      {book.status === 'done' ? 'Done' : book.status === 'reading' ? 'Reading' : 'To Read'}
    </span>
  );
}

export function example(): string {
  return 'a ? b ? c : d : e';
}
